// Theme for the app: Generated by Claude Opus 5.5
export type ThemeName = 'retro' | 'colorsafe' | 'contrast' | 'mono';

export type Theme = {
  paper: string;       // screen background
  card: string;        // cards, inputs, tab bar
  ink: string;         // text, borders, hard shadows
  muted: string;       // secondary text
  primary: string;     // main button background (orange in retro)
  onPrimary: string;   // text on the main button
  primaryText: string; // primary color when used AS TEXT (darker, readable on white)
  arrowBg: string;     // the square arrow block on buttons
  arrowFg: string;
  hi: string;          // yellow highlight behind headline words, badges
  onHi: string;
  live: string;        // "Live" / status badges
  onLive: string;
  s1: string; s1fg: string; // date-stub / avatar accent 1
  s2: string; s2fg: string; // accent 2
  s3: string; s3fg: string; // accent 3 (also the small corner square)
  disabled: string;    // disabled button background
  borderWidth: number; // outline thickness
};

